(()=>{
'use strict';
const $=id=>document.getElementById(id);
const deckData={deep:Array.isArray(window.HEART_CARDS)?window.HEART_CARDS:[],fun:Array.isArray(window.HEART_FUN_CARDS)?window.HEART_FUN_CARDS:[]};
const freeIds=new Set([1,2,3,21,22,23,41,42,43,61,62,63,81,82,83,101,102,103]);
const categories={
  deep:{de:['Alle Karten','Emotionale Verbundenheit','Liebe & Beziehungen','Vertrauen & Verletzlichkeit','Träume & Zukunft','Fernbeziehung','Liebes-Challenges'],en:['All cards','Emotional Connection','Love & Relationships','Trust & Vulnerability','Dreams & Future','Long-Distance Love','Love Challenges']},
  fun:{de:['Alle Karten','Lach dich verliebt','Frech & verspielt','Trau dich, albern zu sein','Was wäre dir lieber?','Liebenswertes Chaos','Mission Liebe'],en:['All cards','Laugh Out Loud','Flirt Alert','Dare to Be Silly','Would You Rather','Couple Chaos','Love Challenges']}
};
const translations={
 de:{tagline:'220 Fragen für Liebe, Nähe und ganz besondere Momente.',questions:'Fragen',play:'Jetzt spielen ♥',eightLanguages:'8 Sprachen',twoDecks:'2 Kartendecks',categories:'Kategorien',favorites:'Favoriten',couple:'Paarmodus',settings:'Einstellungen',home:'Home',yourDeck:'DEIN KARTENDECK',category:'Kategorie',previous:'Zurück',next:'Nächste Karte',save:'Merken',saved:'Gespeichert',shuffle:'Mischen',previewNote:'Design-Prototyp · Premium-Karten sind weiterhin geschützt.',categoryLead:'Wähle eine Sammlung und entdecke passende Fragen.',favoriteLead:'Deine gemerkten Fragen bleiben auf diesem Gerät.',together:'Zusammen spielen, auch auf Distanz',coupleText:'Der echte Paarmodus funktioniert bereits in der bestehenden Test-App. Dieser Prototyp zeigt zunächst nur das neue Design.',openReal:'Funktionierenden Paarmodus öffnen ↗',noMock:'Kein vorgetäuschter Spielraum: Für Live-Synchronisierung öffnet sich die bestehende Testversion.',language:'Sprache der Fragen',langDesc:'Die Kartentexte stammen aus der vorhandenen Sammlung mit acht Sprachen.',aboutTitle:'Über diesen Prototyp',aboutText:'Eine eigenständige Design-Vorschau. Sie ersetzt nicht die veröffentlichte App und nimmt keine Zahlungen entgegen.',premium:'🔒 Premium-Karte – nur in der Vollversion freischaltbar.',empty:'Noch keine Favoriten. Tippe in einer freien Karte auf „Merken“.',select:'Karte auswählen',noData:'Kartendaten konnten nicht geladen werden.'},
 en:{tagline:'220 questions for love, laughter and meaningful moments.',questions:'questions',play:'Start playing ♥',eightLanguages:'8 languages',twoDecks:'2 card decks',categories:'Categories',favorites:'Favorites',couple:'Couple mode',settings:'Settings',home:'Home',yourDeck:'YOUR DECK',category:'Category',previous:'Previous',next:'Next card',save:'Save',saved:'Saved',shuffle:'Shuffle',previewNote:'Design preview · Premium cards remain locked.',categoryLead:'Choose a collection and discover your next conversation.',favoriteLead:'Saved questions stay on this device.',together:'Play together, even miles apart',coupleText:'The real couple mode already works in the existing test app. This prototype demonstrates the new design.',openReal:'Open working couple mode ↗',noMock:'No fake room creation: the real test version handles live synchronization.',language:'Question language',langDesc:'Card content comes from the existing eight-language collection.',aboutTitle:'About this preview',aboutText:'An independent design prototype. It does not replace the published app or process payments.',premium:'🔒 Premium card – unlock in the full app.',empty:'No favorites yet. Save a free card to see it here.',select:'Choose a card',noData:'Card data could not be loaded.'}
};
const locale=()=>translations[lang]||translations.en;
const catLabels=()=>categories[deck][lang]||categories[deck].en;
let lang='de',deck='deep',category='all',pos=0,order=[],flipped=true;
let favorites=new Set();
try{const savedLang=localStorage.getItem('heart-design-lang');if(['de','en','es','fr','zh','ur','hi','ar'].includes(savedLang))lang=savedLang;const saved=JSON.parse(localStorage.getItem('heart-design-favorites')||'[]');if(Array.isArray(saved))favorites=new Set(saved);}catch(e){console.warn('Local preview storage unavailable',e);}
const screens=['home','game','categories','favorites','couple','settings'];
let toastTimer;
function toast(msg){const node=$('toast');node.textContent=msg;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{node.hidden=true;},3000);}
function persist(){try{localStorage.setItem('heart-design-favorites',JSON.stringify([...favorites]));}catch{}}
function setLanguage(value){lang=value;try{localStorage.setItem('heart-design-lang',lang);}catch{}document.documentElement.lang=lang;document.documentElement.dir=['ar','ur'].includes(lang)?'rtl':'ltr';$('languagePicker').value=lang;$('languageShort').textContent=lang.toUpperCase();document.querySelectorAll('[data-i18n]').forEach(el=>{const phrase=locale()[el.dataset.i18n];if(phrase)el.textContent=phrase;});renderCategories();renderFavorites();renderGame();}
function showScreen(screen){if(!screens.includes(screen))return;screens.forEach(name=>{const el=$('screen-'+name);const isCurrent=name===screen;el.hidden=!isCurrent;el.classList.toggle('is-active',isCurrent);});document.querySelectorAll('.nav-item').forEach(btn=>{const yes=btn.dataset.screen===screen||screen==='game'&&btn.dataset.screen==='home';btn.classList.toggle('is-active',yes);if(yes)btn.setAttribute('aria-current','page');else btn.removeAttribute('aria-current');});if(screen==='categories')renderCategories();if(screen==='favorites')renderFavorites();if(screen==='game')renderGame();window.scrollTo({top:0,behavior:'instant'});}
function updateTiles(){document.querySelectorAll('[data-deck]').forEach(btn=>{const active=btn.dataset.deck===deck;btn.classList.toggle('is-selected',active);btn.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-select-deck]').forEach(btn=>btn.classList.toggle('is-active',btn.dataset.selectDeck===deck));}
function buildOrder(){order=deckData[deck].map((card,index)=>({card,index})).filter(item=>category==='all'||Number(item.card.cat)===Number(category)).map(item=>item.index);pos=0;flipped=true;}
function setDeck(value){if(!deckData[value]?.length){toast(locale().noData);return;}deck=value;category='all';buildOrder();updateTiles();renderCategories();renderGame();}
function current(){return deckData[deck][order[pos]];}
function isFree(c){return !!c&&freeIds.has(Number(c.id));}
function question(c){return c&&typeof c[lang]==='string'&&c[lang].trim()?c[lang]:c?.en||c?.de||'';}
function key(c){return deck+':'+c.id;}
function startGame(){if(!deckData[deck].length){toast(locale().noData);return;}buildOrder();showScreen('game');}
function renderGame(){if(!order.length){buildOrder();if(!order.length)return;}const card=current();if(!card)return;$('gameTitle').textContent=deck==='deep'?'Deep Questions':'Love & Laughs';const opts=$('gameCategory');opts.replaceChildren();catLabels().forEach((text,i)=>{const option=document.createElement('option');option.value=i?' '+(i-1):'all';option.value=option.value.trim();option.textContent=text;opts.appendChild(option);});opts.value=category;$('cardNumber').textContent=String(card.id).padStart(2,'0');$('cardCategory').textContent=(catLabels()[Number(card.cat)+1]||'').toUpperCase();$('cardCount').textContent=String(pos+1).padStart(2,'0')+' / '+String(order.length);$('cardLockLabel').textContent=isFree(card)?'':'🔒 PREMIUM';$('cardQuestion').textContent=!flipped?'♡ THE HEART COLLECTION':isFree(card)?question(card):locale().premium;$('cardQuestion').dir=['ar','ur'].includes(lang)?'rtl':'auto';$('favCard').disabled=!isFree(card);$('favCard').firstChild.textContent=favorites.has(key(card))?'♥ ':'♡ ';$('favCard').lastElementChild.textContent=favorites.has(key(card))?locale().saved:locale().save;}
function renderCategories(){const list=$('categoryList');list.replaceChildren();updateTiles();if(!deckData[deck].length)return;catLabels().forEach((name,i)=>{const match=i?' '+(i-1):'all';const value=match.trim();const count=deckData[deck].filter(c=>value==='all'||Number(c.cat)===Number(value)).length;const button=document.createElement('button');button.type='button';button.className='category-row';const left=document.createElement('span');left.textContent=name;const small=document.createElement('small');small.textContent=count+' '+locale().questions;left.appendChild(small);const arrow=document.createElement('span');arrow.className='arrow';arrow.textContent='›';button.append(left,arrow);button.addEventListener('click',()=>{category=value;buildOrder();showScreen('game');});list.appendChild(button);});}
function renderFavorites(){const list=$('favoritesList');list.replaceChildren();const saved=[...favorites].filter(x=>/^(deep|fun):\d+$/.test(x));if(!saved.length){const el=document.createElement('p');el.className='empty-state';el.textContent=locale().empty;list.appendChild(el);return;}for(const savedKey of saved){const [d,id]=savedKey.split(':');const c=deckData[d].find(x=>String(x.id)===id);if(!c||!isFree(c))continue;const btn=document.createElement('button');btn.type='button';btn.className='favorite-row';const left=document.createElement('span');left.textContent=question(c);const small=document.createElement('small');small.textContent=d==='deep'?'Deep Questions':'Love & Laughs';left.appendChild(small);const right=document.createElement('span');right.className='arrow';right.textContent='›';btn.append(left,right);btn.addEventListener('click',()=>{setDeck(d);category='all';buildOrder();const target=order.findIndex(i=>Number(deckData[d][i].id)===Number(id));pos=Math.max(target,0);showScreen('game');});list.appendChild(btn);}}
document.querySelectorAll('[data-screen]').forEach(btn=>btn.addEventListener('click',()=>showScreen(btn.dataset.screen)));
document.querySelectorAll('[data-deck]').forEach(btn=>btn.addEventListener('click',()=>setDeck(btn.dataset.deck)));
document.querySelectorAll('[data-select-deck]').forEach(btn=>btn.addEventListener('click',()=>setDeck(btn.dataset.selectDeck)));
$('playNow').addEventListener('click',startGame);
$('prevCard').addEventListener('click',()=>{if(!order.length)return;pos=(pos-1+order.length)%order.length;flipped=true;renderGame();});
$('nextCard').addEventListener('click',()=>{if(!order.length)return;pos=(pos+1)%order.length;flipped=true;renderGame();});
$('flipCard').addEventListener('click',()=>{flipped=!flipped;renderGame();});
$('favCard').addEventListener('click',()=>{const c=current();if(!isFree(c))return;const k=key(c);if(favorites.has(k))favorites.delete(k);else favorites.add(k);persist();renderGame();});
$('shuffleCard').addEventListener('click',()=>{for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}pos=0;flipped=true;renderGame();toast(locale().shuffle+' ✓');});
$('gameCategory').addEventListener('change',e=>{category=e.target.value;buildOrder();renderGame();});
$('languageQuick').addEventListener('click',()=>showScreen('settings'));
$('languagePicker').addEventListener('change',e=>setLanguage(e.target.value));
if(!deckData.deep.length||!deckData.fun.length)toast(locale().noData);
buildOrder();setLanguage(lang);showScreen('home');
})();